changeSet.sql:
ALTER TABLE cash_closes DROP CONSTRAINT IF EXISTS uq_cash_closes_branch_date_shift;
CREATE UNIQUE INDEX uq_cash_closes_branch_date_shift_active
    ON cash_closes (branch_id, business_date, shift_type_id)
    WHERE status <> 'VOIDED';

rollback.sql:
DROP INDEX IF EXISTS uq_cash_closes_branch_date_shift_active;
ALTER TABLE cash_closes
    ADD CONSTRAINT uq_cash_closes_branch_date_shift
    UNIQUE (branch_id, business_date, shift_type_id);
